'use strict';

const isRunningInEditor = engine.isRunningInEditor()
const debugMode = isRunningInEditor && false
const tips = isRunningInEditor && true
const globalReplayable = true

/*

	Custom Events

*/

class Event {
	/**
	* @param {Hashable} eventID
	* @param {ILayer} layer
	* @param {IObject} object
	* @param {any} eventData
	*/
	constructor(eventID, eventData) {
		this.srcLayer = thisLayer;	// 由于类将在源脚本进行实例化，所以此处变量将指向调用源的父级对象
		this.srcObject = thisObject;
		this.id = eventID;
		this.data = eventData;
		this.interrupted = false;
	}

	interruptDispatch() {
		if (debugMode) {
			console.log('DEBUG: Event "' + this.id + '" dispatch has been interrupted.')
		}
		this.interrupted = true
	}
}

class Listener {
	/**
	* @param {Hashable} listenerID
	* @param {ILayer} layer
	* @param {IObject} object
	* @param {any} eventData
	*/
	constructor(listenerID, callback, priority = 0, data = null) {
		this.thisLayer = thisLayer	// 由于类将在源脚本进行实例化，所以此处变量将指向调用源的父级对象
		this.thisObject = thisObject
		this.id = listenerID;
		this.callback = callback;
		this.priority = priority;
		this.data = data
	}
}

class EventType {
	/**
	* @param {Hashable} eventID
	* @param {string} eventName
	*/
	constructor(eventID, eventName = null, skipDebug = false) {
		this.id = eventID
		this.debug = !skipDebug
		this.name = eventName
		this.listeners = new Map()
		this.sortedListeners = [];
		this.sorted = false;
		this.hasListener = false
	}

	/**
	* @param {Hashable} listenerID
	* @param {function} callback
	* @param {Number} priority
	*/
	addListener(listenerID, callback, priority = 0, data = null) {
		if (this.listeners.has(listenerID)) {
			console.log('WARNING: Listener ID "' + listenerID + '" is already registered. New Registration operation has been ignored.')
			return
		}
		this.listeners.set(listenerID, new Listener(listenerID, callback, priority, data))
		this.sorted = false
		this.hasListener = true
	}

	sortCallbacks() {
		if (this.sorted) {
			return
		}
		this.sortedListeners = Array(this.listeners.values())
		this.sortedListeners.sort((a, b) => b.priority - a.priority)
		this.sorted = true;
	}

	tryCallback(event, listener) {
		try {
			listener.callback(event, listener)
		} catch (err) {
			console.log('WARNING: An error occurs when dispatching event "' + event.id + '" to listener "' + listener.id + '": ' + err)
			console.log('You can set the "callbackWithoutTry" property of the event dispatcher to "true" to prevent catching errors for debugging purposes.')
		}
	}

	callback(event, listener) {
		listener.callback(event, listener)
	}

	/**
	* @param {Event} event
	*/
	dispatchToAll(event) {
		if (!this.hasListener) {
			return
		}
		this.sortCallbacks()
		let cbFunc = eventDispatcher.callbackWithoutTry ? this.callback : this.tryCallback
		if (debugMode && this.debug) {
			console.log('DEBUG: Dispatching event "' + event.id + '" to listeners [ ' + Array(this.listeners.values()).map((listener) => { return listener.id }).join(", ") + ' ]')
		}
		for (let listener of this.listeners.values()) {
			cbFunc(event, listener)
			if (event.interrupted) {
				break
			}
		}
	}

	/**
	* @param {Hashable} listenerID
	* @param {Event} event
	*/
	dispatchToListener(listenerID, event) {
		if (!this.hasListener) {
			return
		}
		let listener = this.listeners.get(listenerID)
		if (listener == undefined) {
			console.log('WARNING: Listener ID "' + listenerID + '" does not exist')
			return
		}
		this.sortCallbacks()
		listener.callback(event, listener)
	}
}

class EventDispatcher {
	constructor() {
		this.eventTypes = new Map()
		this.dispatching = false
		this.tasks = []
		this.callbackWithoutTry = false		// 调试时使用
	}

	/**
	* @param {Hashable} eventID
	* @param {string} eventName
	*/
	registerEvent(eventID, eventName = null, skipDebug = false) {
		if (this.eventTypes.has(eventID)) {
			return false
		}
		this.eventTypes.set(eventID, new EventType(eventID, eventName, skipDebug))
		return true
	}

	/**
	* @param {Hashable} eventID
	* @param {Hashable} listenerID
	* @param {function} callback
	* @param {Number} priority
	*/
	registerListener(eventID, listenerID, callback, priority = 0, data = null) {
		let eventType = this.eventTypes.get(eventID)
		if (eventType == undefined) {
			console.log('WARNING: Event ID "' + eventID + '" does not exist')
			return false
		}
		eventType.addListener(listenerID, callback, priority, data)
		return true
	}

	/**
	* @param {Event} event
	*/
	dispatchEventToAll(event, autoWait = true, log = true) {
		let eventType = this.eventTypes.get(event.id)
		if (eventType == undefined) {
			if (log) {
				console.log('WARNING: Event ID "' + event.id + '" does not exist')
			}
			return
		}
		if (autoWait) {
			if (this.dispatching) {
				this.tasks.push([event])
				return
			}
			this.dispatching = true
			eventType.dispatchToAll(event)
			this.dispatching = false
			this.nextTask()
		} else {
			eventType.dispatchToAll(event)
		}
	}

	/**
	* @param {Hashable} listenerID
	* @param {Event} event
	*/
	dispatchEventToListener(listenerID, event, autoWait = true, log = true) {
		let eventType = this.eventTypes.get(eventID)
		if (eventType == undefined) {
			if (log) {
				console.log('WARNING: Event ID "' + event.id + '" does not exist')
			}
			return
		}
		if (autoWait) {
			if (this.dispatching) {
				this.tasks.push([listenerID, event])
				return
			}
			this.dispatching = true
			eventType.dispatchToListener(listenerID, event)
			this.dispatching = false
			this.nextTask()
		} else {
			eventType.dispatchToListener(listenerID, event)
		}
	}

	nextTask() {
		if (this.dispatching || this.tasks.length == 0) {
			return
		}
		let task = this.tasks.shift()
		if (task.length == 1) {
			this.dispatchEventToAll(task[0])
		} else {
			this.dispatchEventToListener(task[0], task[1])
		}
	}
}

