	*/
	bindBackwardTaskList(taskList) {
		this.backwardTaskList = taskList
		this.backwardTaskList.runningAnis = this.runningAnis
	}

	cleanUpRunningAniList() {
		let ani;
		for ([ani] of this.runningAnis.values()) {
			if (ani.ended) {
				this.runningAnis.delete(ani.aid)
			}
		}
	}

