		} else if (aniScheduler.aniTasks.has(this.tid)) {
			return
		}
		this.active = true
		if (this.backwardTaskList != null) {
			this.backwardTaskList.removeTask()
		}
		aniScheduler.aniTasks.set(this.tid, this)
		this.cleanUpRunningAniList()
		if (this.runningAnis.size != 0) {
			if (debugMode) {
				console.log('DEBUG: ContinuousAnimation [' + Array.from(this.runningAnis.values()).map((data) => {return data[0].ani.name}).toString() + '] in AnimationTaskList ' + this.name + ' is interrupted.')
			}
